BASE = "c09d3e20b9c45c80b34ae3781440d90904a44023"
BEFORE = {"docs/source/developer_guide/kimi_k3_qfm_c8.md":None,"tests/e2e/nightly/single_node/ops/singlecard_ops/check_kimi_k3_qfm_writer.py":None,"tests/ut/attention/test_kimi_k3_qfm_cpu.py":None,"vllm_ascend/ascend_config.py":"8595413ba51a2545589d8900148e228293af73c38f4460e740d66fdf962f7d32","vllm_ascend/attention/context_parallel/mla_cp.py":"250d717e1549e5f5042f6aadcd24a795ed5698a5fd05471659b6e04cc690ccff","vllm_ascend/attention/kimi_k3_qfm.py":None,"vllm_ascend/attention/mla_v1.py":"ccb3aa58d81a32e1468439dc4a9c28dd5d46e385488e7c701db2eb79c9513e5b","vllm_ascend/core/kv_cache_interface.py":"9eb012b6582654000185467b58221dd2628176dc6661d6af1e6d3070a2bc0d03","vllm_ascend/worker/v2/attn_utils.py":"b1e7d441168a5c96f2364199f9092c8b0b95b297393c63dc31dbb19beae8e160","vllm_ascend/worker/v2/model_runner.py":"533986687a50caa40afe7d3610d5fd9fb7d64d0ef167d95fe2c656bf0a3ccec5"}
AFTER = {"docs/source/developer_guide/kimi_k3_qfm_c8.md":"254a67ece18276eb472c615579174889c32c98f0a28941b06c05f34a98fcf59c","tests/e2e/nightly/single_node/ops/singlecard_ops/check_kimi_k3_qfm_writer.py":"fa6b28f5728dbae037cc5a2b419ed682ce8262de4e1bdae00848d562b8232892","tests/ut/attention/test_kimi_k3_qfm_cpu.py":"df6e8aa6f5f69267b2f0d1f74b4433a0868043813ac57d4cca9bcd72e9f3353e","vllm_ascend/ascend_config.py":"db3eb2122e36034696f54af47b6028e61347bad9f8e88d2baaede6b68a6d7056","vllm_ascend/attention/context_parallel/mla_cp.py":"7fc8a0f2ddc782f93dd21cfcb325cd181619ad501afa439dd7929b04e8361f01","vllm_ascend/attention/kimi_k3_qfm.py":"faa1e4aff2ee4eccfd052d4b89494df6584ea0fd7049c1e2f3781c03e30cf240","vllm_ascend/attention/mla_v1.py":"f0c45caf5d2bf70dea3fb0ba9e74c04f0482a477eff7f801b420bd02cc0f0f8e","vllm_ascend/core/kv_cache_interface.py":"5017fe57ce4f231ebb4153b75449b4b3e84171df9396345c711c9797ac924a9b","vllm_ascend/worker/v2/attn_utils.py":"826132dbce47b716dda317e45871541211f20d4b0b70deeedc4eb637446890df","vllm_ascend/worker/v2/model_runner.py":"49ed9001946dd5fd5783676ec1c3360c67a22431a01245f44594a535cfe774b3"}
PATCH_SHA = "0bbe06cd8f4e90cdba60e71b99e518c2a819cc435078ab593e5e09b80903ac96"
PAYLOAD = ""


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None


def installed_source():
    dist = importlib.metadata.distribution("vllm-ascend")
    direct = json.loads(dist.read_text("direct_url.json") or "{}")
    if direct.get("dir_info", {}).get("editable") and direct.get("url", "").startswith("file:"):
        return pathlib.Path(unquote(urlparse(direct["url"]).path))
    raise SystemExit("Cannot locate editable VA. Pass --source /absolute/path/to/VA.")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=pathlib.Path)
    parser.add_argument("--check", action="store_true", help="Read-only preflight; do not apply.")
    args = parser.parse_args()
    root = (args.source or installed_source()).resolve()
    if not (root / "vllm_ascend/ascend_config.py").is_file():
        raise SystemExit("Not a VA source directory: " + str(root))
    for name in AFTER:
        path = root / name
        if not path.resolve().is_relative_to(root) or path.is_symlink():
            raise SystemExit("Refusing symlink/outside source target: " + name)
    actual = {name: digest(root / name) for name in AFTER}
    if actual == AFTER:
        print("QFM_VA030_ALREADY_APPLIED source=" + str(root))
        return
    head = subprocess.check_output(["git", "-C", str(root), "rev-parse", "HEAD"], text=True).strip()
    if head != BASE:
        raise SystemExit("Base mismatch: expected " + BASE + ", got " + head + "; no files changed.")
    mismatch = [name for name in BEFORE if actual[name] != BEFORE[name]]
    if mismatch:
        raise SystemExit("Affected files differ from pinned base; no files changed:\n" + "\n".join(mismatch))
    patch = gzip.decompress(base64.b64decode(PAYLOAD))
    if hashlib.sha256(patch).hexdigest() != PATCH_SHA:
        raise SystemExit("Embedded patch checksum failed; no files changed.")
    subprocess.run(["git", "-C", str(root), "apply", "--check", "-"], input=patch, check=True)
    if args.check:
        print("QFM_VA030_PREFLIGHT_OK source=" + str(root))
        return
    backup = pathlib.Path(tempfile.mkdtemp(prefix="va030-qfm-backup-"))
    for name, old_hash in BEFORE.items():
        if old_hash is not None:
            dest = backup / name
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(root / name, dest)
    (backup / "manifest.json").write_text(json.dumps({"source": str(root), "base": BASE, "before": BEFORE, "after": AFTER}, indent=2))
    subprocess.run(["git", "-C", str(root), "apply", "-"], input=patch, check=True)
    if any(digest(root / name) != expected for name, expected in AFTER.items()):
        raise SystemExit("Post-apply hash mismatch. Stop and inspect; backup=" + str(backup))
    for name in AFTER:
        if name.endswith(".py"):
            compile((root / name).read_text(), name, "exec")
    print("QFM_VA030_APPLIED source=" + str(root))
    print("BACKUP=" + str(backup))
    print("No native packages installed; no NPU/model tests run.")
    print("NEXT: load the pinned native runtime, then run:")
    print("python " + str(root / "tests/e2e/nightly/single_node/ops/singlecard_ops/check_kimi_k3_qfm_writer.py") + " --card 0")
    print("Use enable_kimi_k3_qfm_c8=true, enable_mlapo=false, enable_kv_nz=false.")
    print("qfm_kv_scale must be explicit. 0.03125 is synthetic, for wiring experiments only.")
    print("Restart all workers; never reuse old packed656 cache pages.")


if __name__ == "__main__":
    main()
